class Solution:
    def smallestRangeII(self, nums: List[int], k: int) -> int:
        nums.sort()
        ans = nums[-1] - nums[0]

        for i in range(0, len(nums) - 1):
            ans = min(ans, max(nums[i] + k, nums[-1] -
                      k) - min(nums[i+1] - k, nums[0] + k))

        return ans

class Solution:
    def smallestRangeII(self, A, K):
        A.sort()
        result = A[-1]-A[0]
        for i in range(len(A)-1):
            result = min(result,
                         max(A[-1]-K, A[i]+K) -
                         min(A[0]+K, A[i+1]-K))
        return result

